src/book.sh:2:# book.sh ROOM DATE START END WHO: add a booking unless the room is taken at that time.
src/book.sh:12:  if overlaps "$s" "$e" "$(to_min "$bs")" "$(to_min "$be")"; then echo "conflict: $r $d $bs-$be $bw" >&2; exit 1; fi
src/lib/slots.sh:4:# overlaps S1 E1 S2 E2 (minutes): succeeds when the two bookings share time.
src/lib/slots.sh:5:overlaps() { [ "$1" -le "$4" ] && [ "$3" -le "$2" ]; }
src/list.sh:2:# list.sh [DATE]: bookings, one per line "DATE START-END ROOM WHO", sorted. src/remind.sh reads this.
src/remind.sh:3:bash "$(dirname "$0")/list.sh" "$1" | while read -r d t r w; do echo "reminder to $w: $r $d $t"; done
spec/slots.spec.sh:4:overlaps 600 660 630 700 || { echo "overlap: 10:00-11:00 vs 10:30-11:40"; fail=1; }
spec/slots.spec.sh:5:overlaps 600 720 630 650 || { echo "overlap: containment"; fail=1; }
spec/slots.spec.sh:6:! overlaps 600 660 700 760 || { echo "apart: 10:00-11:00 vs 11:40-12:40"; fail=1; }
# 0003 予約の受付期間を 60 日から 90 日に延ばす

状態: accepted / 日付: 2026-10-20 / 決めた人: @po-lead

利用部署からの要望（四半期の計画会議を 3 か月前に押さえたい）により、予約できる期間を当日から 90 日先までにする。
docs/design/booking-rules.md §日付 の「60 日」を本決定で置き換える。実装は Issue #64。

